struct Fuzz {
extension GrammarNodeKind {
    var isTerminal: Bool { self == .T || self == .TI || self == ./*c*/C || self == .B }
    var isBracket:  Bool { self == .DO || self == .OPT || self == .KLN || self == .POS }
    var isLeaf:     Bool { isTerminal || self == .EPS }
    var isClosure:  Bool { self == .KLN || self == .POS }
}
}

